update public.money_debts set name='Agro', monthly_plan=0, monthly_plan_history=jsonb_set(coalesce(monthly_plan_history,'{}'::jsonb), '{2026-09}', '0'::jsonb, true) where lower(name) in ('agro credit','agro');
